function ficha([slug, t, resp, pron, en, es]) {
  return {
    slug, t, tipo: 'diferencia', comun: true, resp, pron,
    uso: [
      `Esta duda aparece con frecuencia porque las dos formas se parecen, pero no se usan igual. ${resp}`,
      `Mira la estructura y el contexto antes de elegir. El ejemplo muestra una opción natural en inglés estadounidense; escucha el audio y repítelo en voz alta.`
    ],
    ej: [[en, es]],
    truco: `No traduzcas palabra por palabra: identifica qué idea quieres expresar y elige la forma que corresponde al contexto.`,
    prac: 'vocabulary'
  };
}

// El lote editorial de esta publicación son exactamente 200 fichas nuevas.
// Se conserva el banco ampliado abajo para próximas tandas, sin publicar ni
// indexar términos adicionales antes de su revisión editorial.
module.exports = fichas
  .filter(([slug]) => slug !== 'person-vs-people') // ya existe en el glosario anterior
  .slice(0, 200)
  .map(ficha);
